import{_ as t,c as e,o as s,ah as p,ao as a,ap as n}from"./chunks/framework.Dq2_gudl.js";const g=JSON.parse('{"title":"참새 한 마리도 잊히지 않습니다 — 그 아이는 결코 외면받지 않았습니다","description":"예수님은 참새 한 마리 떨어져도 하늘 아버지가 아신다고 하셨습니다. 마태복음과 시편이 말하는 동물을 향한 하나님의 돌보심.","frontmatter":{"title":"참새 한 마리도 잊히지 않습니다 — 그 아이는 결코 외면받지 않았습니다","description":"예수님은 참새 한 마리 떨어져도 하늘 아버지가 아신다고 하셨습니다. 마태복음과 시편이 말하는 동물을 향한 하나님의 돌보심."},"headers":[],"relativePath":"ko/pets-in-heaven/not-one-sparrow-forgotten.md","filePath":"ko/pets-in-heaven/not-one-sparrow-forgotten.md"}'),r={name:"ko/pets-in-heaven/not-one-sparrow-forgotten.md"};function i(l,o,c,h,d,u){return s(),e("div",null,[...o[0]||(o[0]=[p('<div class="pl-quote"><p>「그 아이는 그냥 작은 동물이었어요. 세상이 기억해 줄까요? 아니면 저 혼자일까요?」</p><p class="pl-quote-soft">예수님은 이 질문에 한 번 답하셨고, 그 대답은 우리가 기대하는 것보다 더 다정합니다.</p></div><section class="pl-section"><h2>1. 예수님은 말씀하셨습니다: 참새 한 마리도 아버지 없이는 떨어지지 않는다</h2><blockquote><p><strong>마태복음 10:29-31</strong></p><p>&quot;Are not two sparrows sold for a farthing? and one of them shall not fall on the ground without your Father. But the very hairs of your head are all numbered. Fear ye not therefore, ye are of more value than many sparrows.&quot;</p></blockquote><p>예수님 시대에 참새는 살 수 있는 가장 싼 것 중 하나였습니다. 한 푼에 두 마리. 아무도 특별히 신경 쓰지 않는 그런 생명이었습니다.</p><p>그런데 예수님은 말씀하셨습니다. <strong>너희 아버지가 허락하지 않으시면 그 하나도 땅에 떨어지지 않는다.</strong></p><p>여기서 「떨어지다」는 곧 죽음을 뜻합니다. 예수님은 가장 싼 새의 죽음조차 하나님이 모르는, 신경 쓰지 않는 사고가 아니라고 하십니다. 그 아이의 떠남은 보이셨고, 기록되었습니다.</p><p>당신의 아이가 세상이 「그냥 동물」이라 부르는 작은 존재였다면, 이 구절은 당신을 위해 쓰인 것입니다. 하나님은 참새를 기억하십니다. 당신의 아이를 잊지 않으십니다.</p></section><section class="pl-section"><h2>2. 그 아이를 먹이셨습니다 — 하루도 빠뜨리지 않고</h2><blockquote><p><strong>시편 147:9</strong></p><p>&quot;He giveth to the beast his food, and to the young ravens which cry.&quot;</p></blockquote><p>다윗은 또 이렇게 썼습니다.</p><blockquote><p><strong>시편 36:6</strong></p><p>&quot;…O LORD, thou preservest man and beast.&quot;</p></blockquote><p>「사람과 짐승」— 원어의 이 단어는 들짐승과 집짐승을 모두 포함합니다. 하나님은 동물을 보존하시는 목록에 넣으셨습니다. 곁다리로가 아니라 우리와 나란히요.</p><p>무슨 뜻일까요? 첫날부터 마지막 날까지, 모든 끼니, 모든 겨울, 당신이 집에 없던 모든 시간에도 하나님이 그 아이를 보고 계셨다는 뜻입니다. 당신은 혼자 돌본다고 생각했지만, 하나님과 함께 돌본 것입니다.</p></section><section class="pl-section"><h2>3. 그 아이는 하나님께 속해 있습니다 — 가장 안전한 곳입니다</h2><blockquote><p><strong>시편 50:10-11</strong></p><p>&quot;For every beast of the forest is mine, and the cattle upon a thousand hills. I know all the fowls of the mountains: and the wild beasts of the field are mine.&quot;</p></blockquote><p>하나님은 말씀하십니다. 「수풀의 모든 짐승이 다 내 것이며, 일천 산의 가축도 그러하다. 산의 모든 새도 내가 알며 들의 짐승도 다 내 것이다.」</p><p>당신의 아이는 한 번도 당신의 소유였던 적이 없습니다. 하나님이 당신에게 맡기신 선물이었습니다. 선물을 주신 분이 그것을 다시 가져가실 때, 그분은 그것을 버리지 않으시고 <strong>자기 곁으로 데려가십니다</strong>.</p><p>지금 그 아이를 어떻게 돌보시는지, 어디 있는지, 당신의 목소리를 기억하는지는 모릅니다. 하지만 그게 누구의 손인지는 압니다. 참새까지 세신 그 손입니다.</p><p class="pl-quote-soft">오늘 한 문장만 붙잡을 수 있다면, 이 문장을 붙잡으세요:</p></section><div class="pl-quote"><p>「그 아이는 하나님의 시야에서 한 번도 벗어난 적이 없습니다. 지금도요.」</p></div><section class="pl-section"><h2>이렇게 기도해 볼 수 있습니다</h2><p>「주님, 그 아이를 제게 맡겨 주셔서 감사합니다.<br>제가 보지 못하는 곳에서도 돌보아 주셔서 감사합니다.<br>이제는 안을 수 없지만, 주님의 손이 제 손보다 크다는 것을 압니다.<br>참새 하나도 돌보시듯 그 아이를 돌보아 주세요.<br>그리고 저도 돌보아 주세요. 너무 보고 싶습니다. 아멘.」</p><p><a href="/ko/pets-in-heaven/">← Pets in Heaven으로 돌아가기</a> ｜ 다음 글: <a href="/ko/pets-in-heaven/rainbow-bridge-covenant">무지개 다리 건너편</a></p></section><div class="pl-cta"><h2>그 아이에게는 이름이 있습니다.</h2><p>PetLoss에 그 아이의 이름과, 당신만 알던 작은 습관 하나를 적어 보세요. 그런 디테일은 간직될 가치가 있습니다.</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">App Store에서 다운로드</a></div><div class="pl-bible"><h3>말씀이 계속 곁에 있도록</h3><p>이 글의 모든 구절은 성경에서 왔습니다. 무지개 성경 위젯 앱으로 언제든 말씀을 읽고 매일 말씀 위젯을 설정해 보세요. 그리운 날들에 작은 등불이 되어 줄 것입니다.</p><div class="pl-bible-shots"><figure><img src="'+a+'" alt="Rainbow Bible 홈 화면 위젯 — 2 Timothy 2:13" loading="lazy"><figcaption>매일 말씀을 홈 화면에</figcaption></figure><figure><img src="'+n+'" alt="Rainbow Bible — 하늘나라의 반려동물 주제, 마태복음 10:29-31" loading="lazy"><figcaption>「하늘나라의 반려동물」 주제로 전환해 읽기</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">App Store에서 무지개 성경 위젯 받기</a></div>',8)])])}const b=t(r,[["render",i]]);export{g as __pageData,b as default};
